<?php

declare(strict_types=1);

namespace StripeSDK\DTOs\Payment;

/**
 * payment_method_details_payment_record_pix
 */
final class MethodDetailsPaymentRecordPix extends \Dmorenof\SdkRuntime\DTO
{
    protected const array VALIDATION = [
        'bank_transaction_id' => [
            'maxLength' => 5000,
        ],
        'mandate' => [
            'maxLength' => 5000,
        ],
    ];

    /**
     * Unique transaction id generated by BCB
     */
    public ?string $bank_transaction_id {
        set {
            $this->assigning('bank_transaction_id', $value);
            $this->bank_transaction_id = $value;
        }
    }
    /**
     * ID of the multi use Mandate generated by the PaymentIntent or SetupIntent.
     */
    public string $mandate {
        set {
            $this->assigning('mandate', $value);
            $this->mandate = $value;
        }
    }

    protected function assignMember(string $name, mixed $value): void
    {
        match ($name) {
            'bank_transaction_id' => $value === null || is_string($value) ? $this->bank_transaction_id = $value : parent::assignMember($name, $value),
            'mandate' => is_string($value) ? $this->mandate = $value : parent::assignMember($name, $value),
            default => parent::assignMember($name, $value),
        };
    }
}
